begin;
select no_plan();
select has_function('public','m365_finish_refresh',array['uuid','uuid','uuid','bytea','text','timestamp with time zone','bytea','bytea','timestamp with time zone','text[]'],'AC-M365DOC-070 refresh completion contract exists');
insert into public.organizations(id,name) values('10220000-0000-0000-0000-000000000001','Synthetic refresh org');
insert into auth.users(id,email) values('10220000-0000-0000-0000-000000000101','refresh@example.invalid');
insert into public.profiles(id,org_id,full_name,email,role,status) values('10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000001','Synthetic member','refresh@example.invalid','Project Manager','active');
insert into public.org_features(org_id,feature_key,enabled) values('10220000-0000-0000-0000-000000000001','m365_integration',true);
insert into public.ms_graph_connections(id,org_id,user_id,entra_tenant_id,scopes,refresh_token_ciphertext,key_id,status)
values('10220000-0000-0000-0000-000000000201','10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','synthetic-tenant',array['Files.Read','Sites.Selected','offline_access'],decode(repeat('01',28),'hex'),'kek-v1','active');
select ok(not has_function_privilege('authenticated','public.m365_finish_refresh(uuid,uuid,uuid,bytea,text,timestamptz,bytea,bytea,timestamptz,text[])','execute'),'AC-M365DOC-070 client completion is not callable');
select ok(not has_function_privilege('anon','public.m365_finish_refresh(uuid,uuid,uuid,bytea,text,timestamptz,bytea,bytea,timestamptz,text[])','execute'),'AC-M365DOC-070 anonymous completion is not callable');
select ok(has_function_privilege('service_role','public.m365_finish_refresh(uuid,uuid,uuid,bytea,text,timestamptz,bytea,bytea,timestamptz,text[])','execute'),'AC-M365DOC-070 service completion is callable');
select ok((select proconfig @> array['search_path=pg_catalog, public'] from pg_proc where oid='public.m365_finish_refresh(uuid,uuid,uuid,bytea,text,timestamptz,bytea,bytea,timestamptz,text[])'::regprocedure),'AC-M365DOC-070 completion pins its namespace');
set local role service_role;
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000201',decode(repeat('02',28),'hex'),'stale',now()),null::uuid,'AC-M365DOC-070 completion compares the original token generation');
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000201',decode(repeat('01',28),'hex'),'active',now(),decode(repeat('03',28),'hex'),decode(repeat('04',28),'hex'),now()+interval '1 hour',array['Files.Read','offline_access']), '10220000-0000-0000-0000-000000000201'::uuid,'AC-M365DOC-070 matching completion rotates the pair');
reset role;
select is((select scopes from public.ms_graph_connections where id='10220000-0000-0000-0000-000000000201'),array['Files.Read','offline_access'],'AC-M365DOC-070 completion stores the current grant');
set local role service_role;
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000201',decode(repeat('01',28),'hex'),'revoked',now()),null::uuid,'AC-M365DOC-070 an earlier completion leaves the newer pair intact');
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000201',decode(repeat('04',28),'hex'),'active',now(),decode(repeat('05',28),'hex'),decode(repeat('06',28),'hex'),now()+interval '1 hour',array['Files.Read','Sites.Selected','offline_access']),null::uuid,'AC-M365DOC-070 refresh preserves consent bounds');
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000102','10220000-0000-0000-0000-000000000201',decode(repeat('04',28),'hex'),'stale',now()),null::uuid,'AC-M365DOC-070 completion is bound to the member');
reset role;
select is((select status from public.ms_graph_connections where id='10220000-0000-0000-0000-000000000201'),'active','AC-M365DOC-070 current connection remains active');
update public.ms_graph_connections set status='revoked' where id='10220000-0000-0000-0000-000000000201';
set local role service_role;
select is(public.m365_finish_refresh('10220000-0000-0000-0000-000000000001','10220000-0000-0000-0000-000000000101','10220000-0000-0000-0000-000000000201',decode(repeat('04',28),'hex'),'active',now(),decode(repeat('05',28),'hex'),decode(repeat('06',28),'hex'),now()+interval '1 hour',array['Files.Read','offline_access']),null::uuid,'AC-M365DOC-070 completion preserves a closed connection');
reset role;
select is((select status from public.ms_graph_connections where id='10220000-0000-0000-0000-000000000201'),'revoked','AC-M365DOC-070 closed connection remains closed');
select * from finish();
rollback;
